    ('3b7fc9a8-a685-4e5b-9ae7-df7a0d530d2e'::uuid, 'scope_reason', 'duplicate_of:3c47ded2-01b0-4789-bf6e-defb171ddd43', NULL, 'dup-merge-retire-2026-11-12-rollback:3b7fc9a8-a685-4e5b-9ae7-df7a0d530d2e:scope_reason', 'rollback of dup-merge-retire-2026-11-12: scope_reason None restored on Mycenaean Acropolis of Midea', 'Mycenaean Acropolis of Midea | content links 2, images 15 | enwiki_title=Midea (Argolid), wikidata_qid=Q502897 | survivor Midea, Argolid | enwiki_title=Midea (Argolid), wikidata_qid=Q502897 | live images 15', '[{"source": "identity/dup_judge.py, cluster dup-78079218a1", "url": null, "quote": "MERGE ''Mycenaean Acropolis of Midea'' into ''Midea, Argolid'': The Mycenaean acropolis (citadel) of Midea IS the archaeological site of Midea in the Argolid: the Swedish Institute at Athens, which excavates it, describes ''the acropolis of Midea and its important Late Bronze Age citadel'' on the 270 m conical hill, and the remains of Midea are that citadel. Both records sit 12 m apart on that hill and carry the same item Q502897 and article Midea (Argolid). A possible lower town outside the walls is ''not yet securely identified'' (SIA), so there is no second place for the city record. Survivor ''Midea, Argolid'': the name the site is commonly called in English (Midea), and the fuller text (excavations, Linear B, destruction c. 1200 BC); images (15/15) and links (5/5) are equal, both texts lane L."}, {"quote": "The acropolis of Midea and its important Late Bronze Age citadel is located on a 270 m tall conical hill in the Argolid", "source": "https://www.sia.gr/en/articles.php?tid=339&page=1", "url": "https://www.sia.gr/en/articles.php?tid=339&page=1"}, {"quote": "concluded that Midea was a fortified Mycanean citadel", "source": "https://www.sia.gr/en/articles.php?tid=339&page=1", "url": "https://www.sia.gr/en/articles.php?tid=339&page=1"}, {"quote": "The remains of Midea, that of a Bronze Age citadel, stand above the village of the same name in the Argolid.", "source": "https://en.wikipedia.org/wiki/Midea_(Argolid)", "url": "https://en.wikipedia.org/wiki/Midea_(Argolid)"}, {"quote": "The acropolis of Midea and its important Late Bronze Age citadel is located on a 270 m tall conical hill in the Argolid", "source": "https://www.sia.gr/en/articles.php?tid=339&page=1", "url": "https://www.sia.gr/en/articles.php?tid=339&page=1"}, {"quote": "While not yet securely identified, a large terrace wall and other structural remains suggest that it was located to the north-west.", "source": "https://www.sia.gr/en/articles.php?tid=339&page=1", "url": "https://www.sia.gr/en/articles.php?tid=339&page=1"}, {"quote": "The remains of Midea, that of a Bronze Age citadel, stand above the village of the same name in the Argolid.", "source": "https://en.wikipedia.org/wiki/Midea_(Argolid)", "url": "https://en.wikipedia.org/wiki/Midea_(Argolid)"}, {"source": "production:unified_sites", "url": null, "quote": "''Mycenaean Acropolis of Midea'' (3b7fc9a8-a685-4e5b-9ae7-df7a0d530d2e): 15 image(s), 2 content link(s); survivor ''Midea, Argolid'' (3c47ded2-01b0-4789-bf6e-defb171ddd43): 15 image(s), 8 content link(s); 11.7 m apart (read 2026-11-12 12:27:08.585495+00)"}]'::jsonb),
