    ('5d8a914c-d69d-409c-9713-588113811da5'::uuid, 'scope_reason', 'duplicate_of:3911fbf9-3c1c-4620-a197-10ccbb9e20f7', NULL, 'dup-merge-retire-2026-11-12-rollback:5d8a914c-d69d-409c-9713-588113811da5:scope_reason', 'rollback of dup-merge-retire-2026-11-12: scope_reason None restored on Kalkrieser Berg', 'Kalkrieser Berg | content links 0, images 0 | enwiki_title=Kalkrieser Berg, wikidata_qid=Q767809 | survivor Kalkriese | enwiki_title=Kalkriese, wikidata_qid=Q60176450 | live images 17', '[{"source": "identity/dup_judge.py, cluster dup-65ffa1fc80", "url": null, "quote": "MERGE ''Kalkrieser Berg'' into ''Kalkriese'': Both records stand on one point (7 m apart, both at the Kalkriese find site, Wikidata P625 of Kalkriese 52.408056, 8.129444) and both describe one archaeological site: the Roman battlefield at Kalkriese below the Kalkrieser Berg, identified as the likely site of the Battle of the Teutoburg Forest. The Kalkriese article names the Kalkrieser Berg as that site, and Wikidata labels the hill item Q767809 in English simply ''Kalkriese''. Neither item is the find site''s own (Q60176450 is the village, Q767809 the hill; de article ''Fundregion Kalkriese'' covers the find region), so that link is a matter for the link repair, not for this verdict. Survivor 3911fbf9: ''Kalkriese'' is the name the battlefield is commonly called in English, its Wikipedia-based text covers the excavations and finds, 16 images against 1; content links are equal (5 and 5)."}, {"quote": "The Kalkrieser Berg or Schmittenhöhe, a hill with a height of 157 m (515 ft), is considered by archaeologists to be the likely site of the Battle of the Teutoburg Forest", "source": "https://en.wikipedia.org/wiki/Kalkriese", "url": "https://en.wikipedia.org/wiki/Kalkriese"}, {"quote": "In the area of  Kalkriese artifacts believed to be from the battle have been recovered", "source": "https://en.wikipedia.org/wiki/Kalkrieser_Berg", "url": "https://en.wikipedia.org/wiki/Kalkrieser_Berg"}, {"quote": "The Romans'' saltus Teutoburgiensis (Teutoburg Pass) is taken to refer to the strip of cultivated land with a width of 220 m", "source": "https://en.wikipedia.org/wiki/Kalkriese", "url": "https://en.wikipedia.org/wiki/Kalkriese"}, {"quote": "In the area of  Kalkriese artifacts believed to be from the battle have been recovered", "source": "https://en.wikipedia.org/wiki/Kalkrieser_Berg", "url": "https://en.wikipedia.org/wiki/Kalkrieser_Berg"}, {"quote": "Engpass zwischen dem Großen Moor im Norden und dem Kalkrieser Berg", "source": "https://de.wikipedia.org/wiki/Fundregion_Kalkriese", "url": "https://de.wikipedia.org/wiki/Fundregion_Kalkriese"}, {"source": "production:unified_sites", "url": null, "quote": "''Kalkrieser Berg'' (5d8a914c-d69d-409c-9713-588113811da5): 0 image(s), 0 content link(s); survivor ''Kalkriese'' (3911fbf9-3c1c-4620-a197-10ccbb9e20f7): 21 image(s), 10 content link(s); 6.7 m apart (read 2026-11-12 12:27:08.585495+00)"}]'::jsonb),
