DO $$
DECLARE
    bad      INTEGER;
    moved    INTEGER := 0;
    expected INTEGER := 58;
    r        RECORD;
BEGIN
    -- expected is the plan's own row count, rendered here, and not a second count of the
    -- temp table the loop below iterates: counting the same table twice would make the
    -- comparison after the loop a tautology. The instance that makes a short loop
    -- unreachable is apply_remediation_change, which raises unless exactly one row
    -- matched; this guard is what reports a loop that changed fewer rows than the plan.

    -- scope guard 1: every planned row is a curated site that still exists
    SELECT count(*) INTO bad
      FROM _dup_merge_retire_plan p LEFT JOIN unified_sites u ON u.id = p.site_id
     WHERE u.id IS NULL OR u.source_id <> 'ancient_nerds';
    IF bad > 0 THEN
        -- the source name is a RAISE argument, never part of the quoted message: a name
        -- spliced into the message text only parses while the name happens to contain no
        -- quote, which is a property of today's value and not of this code. G0's guard is
        -- the shape this one copies.
        RAISE EXCEPTION 'D14 duplicate retirement: % planned row(s) are not % sites', bad, 'ancient_nerds';
    END IF;

    -- scope guard 2: the plan is a set of real changes, each one writable in its column
    -- (compared in the column's own type; CASE, because only CASE fixes the order in
    -- which the casts are evaluated)
    SELECT count(*) INTO bad FROM _dup_merge_retire_plan p
     WHERE p.new_value = '' OR CASE p.column_name
                WHEN 'scope_status' THEN p.new_value::text IS NOT DISTINCT FROM p.old_value::text OR p.old_value IS NULL
                WHEN 'scope_reason' THEN p.new_value::text IS NOT DISTINCT FROM p.old_value::text OR p.old_value IS NULL
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'D14 duplicate retirement: % planned row(s) are not writable changes', bad;
    END IF;

    -- scope guard 3: every planned row still holds the old value the plan names
    SELECT count(*) INTO bad
      FROM _dup_merge_retire_plan p JOIN unified_sites u ON u.id = p.site_id
     WHERE CASE p.column_name
                WHEN 'scope_status' THEN u.scope_status IS DISTINCT FROM p.old_value::text
                WHEN 'scope_reason' THEN u.scope_reason IS DISTINCT FROM p.old_value::text
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'D14 duplicate retirement: % planned row(s) no longer hold the planned old value', bad;
    END IF;

    -- scope guard 4: every planned row undos a value this lane owns (old value)
    SELECT count(*) INTO bad FROM _dup_merge_retire_plan p
     WHERE CASE p.column_name
                WHEN 'scope_status' THEN p.old_value NOT IN ('retired')
                ELSE false END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'D14 duplicate retirement: % planned row(s) undo a value this lane does not own', bad;
    END IF;

    -- scope guard 5: every planned row still holds the input its value was derived from
    SELECT count(*) INTO bad
      FROM (SELECT DISTINCT site_id, premise FROM _dup_merge_retire_plan) p JOIN unified_sites u ON u.id = p.site_id
     WHERE (u.name || ' | ' || 'content links ' || CAST((SELECT count(*) FROM site_content_links c WHERE c.site_id = u.id) AS text) || ', images ' || CAST((SELECT count(*) FROM wiki_images w WHERE w.site_id = u.id) AS text) || ' | ' || coalesce((SELECT string_agg(e.kind || '=' || e.value, ', ' ORDER BY e.kind, e.value) FROM site_external_ids e WHERE e.site_id = u.id), '') || ' | survivor ' || coalesce((SELECT s.name || ' | ' || coalesce((SELECT string_agg(e.kind || '=' || e.value, ', ' ORDER BY e.kind, e.value) FROM site_external_ids e WHERE e.site_id = s.id), '') || ' | live images ' || CAST((SELECT count(*) FROM wiki_images w WHERE w.site_id = s.id AND w.is_excluded IS NOT TRUE) AS text) FROM unified_sites s WHERE s.id = (CASE CAST(u.id AS text) WHEN 'ddc0a0bf-1313-499a-8ec6-77839727afe1' THEN '69aaac26-9f4a-47da-beb4-d31ef8d4301f' WHEN '37008e3f-056c-43dc-81c2-74904cacdb4e' THEN 'a50cf939-77f1-489c-82f7-93b07b2bc5ae' WHEN '63d4e2b3-4dad-438d-be14-34bd79cf9842' THEN 'bf0d9250-fe2f-4f04-9dc7-28bcbfd6da20' WHEN '1758f6e8-4518-43fb-a14a-1ce52caca683' THEN '4200b0d7-2aae-4e07-acf3-a342b0c468ac' WHEN '0abaf157-35d2-478f-8b19-c142f67aa8c7' THEN '1c93058e-d647-4f04-8aba-297c20ad41f2' WHEN 'a2ddd76f-1c37-4ac9-971b-d9682384141d' THEN '03d63367-fb7a-4014-b1db-a704e99a10f3' WHEN '0d7c325a-5370-4a95-b048-8e599f69892c' THEN '9ba7c034-6aec-492e-b66e-4541ce3c987c' WHEN '7814f888-d384-442b-8b6b-72c1b209d1d5' THEN '56836aa2-1680-43fb-aeef-1edcc33e2c91' WHEN '1a76bfc9-7056-4848-ac12-d24016a923bb' THEN 'fe61c9c4-97dc-4478-93f8-5cd4a44d8ec2' WHEN '3bb2d9e1-7e77-4582-8b28-92ab27133a9a' THEN 'b319970d-efcd-4f5c-9d9b-55535771676b' WHEN '434c9060-4b58-46a0-94f4-63a85b7133b9' THEN 'efe2bc83-83cc-4393-b725-a18543dc9d5f' WHEN '5d8a914c-d69d-409c-9713-588113811da5' THEN '3911fbf9-3c1c-4620-a197-10ccbb9e20f7' WHEN '58d2d752-30cc-4f22-b2d5-ff27a4b395d1' THEN '13bdea38-cb6c-4c6b-85cb-402a31427819' WHEN '2048dfe4-9b29-494f-8807-881c71023f22' THEN 'b9fdfd6f-b222-4c64-9953-b04fef1f55aa' WHEN '3b7fc9a8-a685-4e5b-9ae7-df7a0d530d2e' THEN '3c47ded2-01b0-4789-bf6e-defb171ddd43' WHEN 'ab077874-2a7f-4add-adec-8cb42e9e9561' THEN '47eb07cd-5c1c-4c0e-88c0-484d3b3411a1' WHEN '0144891e-136b-40fb-87ec-26f618e36365' THEN '15e95e05-6fb3-4779-bbcd-375cd2f031e0' WHEN '1706b1bf-6c89-4f31-a925-e5e679884794' THEN '53a9ddce-054f-4471-94fd-6243611ae0a8' WHEN '774a99e0-e8f7-4881-aa6e-94462da0c52d' THEN 'a07daa54-5e5d-48c7-a95f-097ce085c9fb' WHEN 'f5df832e-ab5e-4e9c-b6c9-037441011945' THEN 'd4714397-6e73-432d-add3-c01e22cb055f' WHEN 'ca33a292-b102-4efe-b644-48959d8ff741' THEN '9031494a-4710-430f-975c-18c9a5990592' WHEN 'c73b6ca5-aa7d-4737-af90-1e6cbab06ff5' THEN '3f27e34a-1817-4b2b-bc19-c3c17a7e6374' WHEN '9bf829da-096e-41c6-b175-f3436c1ce18c' THEN 'a5232aa9-627c-444a-8ac7-82c5b79c3f2d' WHEN '2fc65539-6b0f-4073-9db3-76dadc408cc8' THEN 'd47439dd-6349-4633-bf0b-eb97094ac743' WHEN 'dcda1568-0730-4cba-a9ce-c50c80ed941d' THEN '0999c397-1333-4ff3-aa26-fe854f46de9c' WHEN '8107d407-8094-4f0b-b459-54b2a43e1864' THEN 'ced822e8-13cd-49db-9011-808dc23aac45' WHEN '5dd5ecd6-2cd4-4e37-ae35-51da8f716d07' THEN '1bc57ad9-041a-42de-b0a1-c361a7beb531' WHEN '41070db5-8f7c-4d69-8652-cc2d4bfb8bf4' THEN '5a2e082b-8ed8-4116-b5c3-5414826f0d92' WHEN '9910d3da-4875-49eb-8da4-3f2db69a48a6' THEN '5a2e082b-8ed8-4116-b5c3-5414826f0d92' WHEN '04d8ce82-4fa3-4e48-88b7-bb41b354260c' THEN '00f522ff-8e1b-4983-961c-ef6cb1ff27d1' WHEN '07fb4e2f-26e5-4720-a949-9c28d4712e11' THEN '9152beea-f7ab-40ef-a692-ef63ac8e9ca6' WHEN '13c3f25f-3887-49c1-9492-cf7e512e5782' THEN '13120650-2e61-45af-976c-b2e0665c49af' WHEN '24676ed3-9308-42d4-bf35-1c739f0652e2' THEN '9d9d94a0-f338-4392-860f-983c29fabb16' WHEN '3ebb514f-ac4a-4913-b54b-409bcc29eff4' THEN '51daf6c9-25d3-4818-8857-0543f1203c57' WHEN '4687a49a-c987-4c56-bc6e-5094aa57667d' THEN 'c6d9487d-d138-4d73-beb1-5735e50da048' WHEN '4a5a324f-832f-4dca-b688-d4a006d297c7' THEN '318414bc-098b-4459-95c0-41e1ec49c8a8' WHEN '4e6247b0-7416-413f-b7a3-b31890a45f3b' THEN '4a9b3802-1067-4f6b-a144-4c2ffe9619a4' WHEN '55a670ec-c7c5-4f52-98ea-b25211aedd4e' THEN '47c37ef9-98ee-41d8-879b-e78db06295da' WHEN '577b13cd-242b-4951-a8c4-ab3ecde0e5b1' THEN '23576019-c749-4ee9-95b1-cdae21f5ff06' WHEN '5a04d6f3-c82d-4c82-b1e9-3d70bff135ae' THEN '56f594fc-6819-4d51-98a4-1cf5b4a265a6' WHEN '7e33b1ac-bb32-4b6c-b070-2c4fdcaf19fb' THEN '109fcdea-c114-4143-87ac-77c4c9c20f16' WHEN '8cecb38f-08cf-4a93-b350-9ccbb74109bb' THEN '5025eee3-28ea-46d6-b2c3-dbb1f38a24d6' WHEN '93391ee6-8e80-42db-922c-11f64ea57db9' THEN '84ef64f3-394a-4b35-ba4a-7e81b3b6a317' WHEN 'ab03fa75-bbdc-46a2-ba55-25e2f5edd5c4' THEN '485c3c0c-31f0-45a7-a06b-797c4c021466' WHEN 'ae2ca7b1-89da-46cb-8924-f9d04dd5da2e' THEN 'ce7db300-8777-425d-917a-2f6d9f325b58' WHEN 'b46b6969-3160-4cbd-a574-8727ee7c53c5' THEN '891ad351-7985-4c16-b6a6-830c26bc268f' WHEN 'cf49332c-0a05-4ba7-bf4f-48a703ee7a1e' THEN '577f2ec4-3dc0-4d10-9425-39f1cb654009' WHEN 'd120ca9a-703b-49e2-b333-ad6dfe508953' THEN '9983bdce-9f35-47a3-a570-4021cfa41b97' WHEN 'dafc7527-c6c8-45c3-8c7d-4813d20a4dcf' THEN 'd41368ba-6aa2-4b75-adf4-8f2cd3cc7e4d' WHEN 'f23a31c3-6833-4df6-8583-3b3930b5a74f' THEN '21ac323f-7214-4891-9499-74e55c3d7d56' END)::uuid), '')) IS DISTINCT FROM p.premise;
    IF bad > 0 THEN
        RAISE EXCEPTION 'D14 duplicate retirement: % planned row(s) no longer hold the premise the plan derived its value from', bad;
    END IF;

    -- the only writer: the conditional UPDATE and its journal row commit together, and
    -- the function raises unless exactly one row matched
    FOR r IN SELECT * FROM _dup_merge_retire_plan ORDER BY site_id, column_name LOOP
        moved := moved + apply_remediation_change(
            'unified_sites', r.column_name, 'id', r.site_id::text,
            r.old_value, r.new_value,
            'D14/dup-merge-retire', '2026-11-12_mechanical-dup-merge-retire-rollback', r.change_key, 'two_source', r.evidence, r.site_id);
    END LOOP;

    IF moved <> expected THEN
        RAISE EXCEPTION 'D14 duplicate retirement: % row(s) changed, % planned', moved, expected;
    END IF;

    -- invariant 1: every planned row now holds the new value
    SELECT count(*) INTO bad
      FROM _dup_merge_retire_plan p JOIN unified_sites u ON u.id = p.site_id
     WHERE CASE p.column_name
                WHEN 'scope_status' THEN u.scope_status IS DISTINCT FROM p.new_value::text
                WHEN 'scope_reason' THEN u.scope_reason IS DISTINCT FROM p.new_value::text
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'D14 duplicate retirement: % planned row(s) do not hold the new value', bad;
    END IF;

    -- invariant 2: the journal and the data agree, row for row, in both directions
    SELECT count(*) INTO bad
      FROM _dup_merge_retire_plan p LEFT JOIN remediation_change_log l
        ON l.row_pk = p.site_id::text AND l.table_name = 'unified_sites'
       AND l.column_name = p.column_name
       AND l.run_stamp = '2026-11-12_mechanical-dup-merge-retire-rollback'
     WHERE l.id IS NULL
        OR l.new_value IS DISTINCT FROM p.new_value
        OR l.old_value IS DISTINCT FROM p.old_value;
    IF bad > 0 THEN
        RAISE EXCEPTION 'D14 duplicate retirement: % planned row(s) have no matching journal row', bad;
    END IF;

    SELECT count(*) INTO bad FROM remediation_change_log l
     WHERE l.run_stamp = '2026-11-12_mechanical-dup-merge-retire-rollback'
       AND (l.table_name <> 'unified_sites' OR l.column_name NOT IN ('scope_status', 'scope_reason'));
    IF bad > 0 THEN
        RAISE EXCEPTION 'D14 duplicate retirement: this run stamp journalled % row(s) outside unified_sites.(scope_status, scope_reason)', bad;
    END IF;

    RAISE NOTICE 'D14 duplicate retirement: % of % planned cell(s) changed and journalled over 29 curated site(s)',
        moved, expected;
END $$;

COMMIT;

-- Post-commit read: the numbers the report quotes, from the database, not from the plan.
SELECT 'journal rows for this run stamp' AS metric, count(*)::text AS value
  FROM remediation_change_log WHERE run_stamp = '2026-11-12_mechanical-dup-merge-retire-rollback'
UNION ALL
SELECT 'journal rows for this test id', count(*)::text
  FROM remediation_change_log WHERE test_id = 'D14/dup-merge-retire'
UNION ALL
SELECT 'planned rows now holding the new value', count(*)::text
  FROM remediation_change_log l
 WHERE l.run_stamp = '2026-11-12_mechanical-dup-merge-retire-rollback' AND l.table_name = 'unified_sites'
   AND l.column_name IN ('scope_status', 'scope_reason')
   AND EXISTS (SELECT 1 FROM unified_sites u
                WHERE u.id::text = l.row_pk AND CASE l.column_name
                WHEN 'scope_status' THEN u.scope_status IS NOT DISTINCT FROM l.new_value::text
                WHEN 'scope_reason' THEN u.scope_reason IS NOT DISTINCT FROM l.new_value::text
                ELSE false END)
UNION ALL
SELECT 'curated rows retired as a duplicate', count(*)::text
  FROM unified_sites
 WHERE source_id = 'ancient_nerds' AND scope_status = 'retired' AND scope_reason LIKE 'duplicate_of:%'
UNION ALL
SELECT 'curated sites', count(*)::text
  FROM unified_sites WHERE source_id = 'ancient_nerds';
